# BioInnovate glossary and reference list.
# Keys are lowercase; lessons write [[term]] or [[shown words|key]]. Definitions were written for the module
# from Betts et al. (2022) and Clark et al. (2018).

def _g(term, d):
    return {'term': term, 'def': d}

GLOSSARY = {
    'aorta': _g('aorta', 'The largest artery. It carries oxygen-rich blood from the left ventricle to the rest of the body.'),
    'arteriole': _g('arteriole', 'A very small artery. Smooth muscle in its wall can narrow or widen it, which controls how much blood reaches a capillary bed.'),
    'artery': _g('artery', 'A blood vessel that carries blood away from the heart. Most arteries carry oxygen-rich blood, but the pulmonary arteries carry oxygen-poor blood.'),
    'atrioventricular valve': _g('atrioventricular valve', 'A valve between an atrium and a ventricle. The tricuspid valve is on the right side of the heart and the mitral valve is on the left.'),
    'atrium': _g('atrium', 'An upper chamber of the heart that receives blood returning to the heart. The plural is atria.'),
    'av node': _g('AV node', 'The atrioventricular node: a small group of cells between the atria and the ventricles. It delays the electrical signal briefly so the atria can empty before the ventricles contract.'),
    'baroreceptor': _g('baroreceptor', 'A stretch sensor in the wall of the aorta and the carotid arteries that detects changes in blood pressure.'),
    'blood pressure': _g('blood pressure', 'The force that blood exerts on the walls of blood vessels. It is measured in millimeters of mercury (mm Hg).'),
    'capillary': _g('capillary', 'The smallest kind of blood vessel. Its wall is one cell thick, so substances can pass between the blood and body cells.'),
    'capillary bed': _g('capillary bed', 'A network of capillaries that connects one arteriole to one venule and supplies a small area of tissue.'),
    'cardiac cycle': _g('cardiac cycle', 'One complete heartbeat: the heart relaxes and fills, then contracts and pumps.'),
    'cardiac output': _g('cardiac output', 'The volume of blood one ventricle pumps in one minute. Cardiac output = heart rate × stroke volume.'),
    'carotid artery': _g('carotid artery', 'One of the two large arteries in the neck that carry blood to the head and brain. Its wall contains baroreceptors.'),
    'chordae tendineae': _g('chordae tendineae', 'Thin, strong cords that tie the flaps of the atrioventricular valves to the papillary muscles. They stop the flaps from being pushed back into the atria.'),
    'closed circulatory system': _g('closed circulatory system', 'A circulatory system in which blood always stays inside the heart and the blood vessels, as in earthworms and all vertebrates.'),
    'coronary arteries': _g('coronary arteries', 'The arteries that branch from the aorta and supply the heart muscle itself with oxygen-rich blood.'),
    'diastole': _g('diastole', 'The part of the cardiac cycle when a heart chamber relaxes and fills with blood.'),
    'diastolic pressure': _g('diastolic pressure', 'The lower number in a blood pressure reading. It is the pressure in the arteries while the ventricles relax.'),
    'diffusion': _g('diffusion', 'The movement of particles from where they are more concentrated to where they are less concentrated.'),
    'double circulation': _g('double circulation', 'A circulation in which blood passes through the heart twice in one full trip: once on the way to the lungs and once on the way to the body.'),
    'heart rate': _g('heart rate', 'The number of heartbeats in one minute.'),
    'hemoglobin': _g('hemoglobin', 'The iron-containing protein in red blood cells that carries oxygen and gives blood its red color.'),
    'homeostasis': _g('homeostasis', 'Keeping conditions inside the body, such as blood pressure, within a narrow healthy range.'),
    'hormone': _g('hormone', 'A chemical messenger released into the blood by a gland. It changes the activity of its target organs.'),
    'hypertension': _g('hypertension', 'Blood pressure that stays too high over time. In the Philippines it is defined as a clinic reading of 140/90 mm Hg or higher, taken on at least two separate days.'),
    'lymph': _g('lymph', 'Fluid that has leaked out of capillaries and is collected by lymph vessels, which return it to the blood.'),
    'mean arterial pressure': _g('mean arterial pressure', 'The average pressure in the arteries during one heartbeat. It is about the diastolic pressure plus one-third of the pulse pressure.'),
    'medulla oblongata': _g('medulla oblongata', 'The part of the brainstem that contains the cardiovascular center, which adjusts heart rate and vessel diameter.'),
    'mitral valve': _g('mitral valve', 'The valve between the left atrium and the left ventricle. It is also called the bicuspid valve.'),
    'myocardium': _g('myocardium', 'The thick middle layer of the heart wall, made of cardiac muscle.'),
    'negative feedback': _g('negative feedback', 'A control process in which a change triggers a response that reverses the change.'),
    'open circulatory system': _g('open circulatory system', 'A circulatory system in which the heart pumps fluid into open spaces around the organs, as in insects and most mollusks.'),
    'papillary muscle': _g('papillary muscle', 'A small cone of muscle in the wall of a ventricle. The chordae tendineae run from it to the flaps of an atrioventricular valve.'),
    'phloem': _g('phloem', 'Plant tissue that carries sugars from where they are made or stored to where they are needed.'),
    'precapillary sphincter': _g('precapillary sphincter', 'A ring of smooth muscle at the entrance to a capillary. It opens and closes to control the flow of blood into a capillary bed.'),
    'pulmonary artery': _g('pulmonary artery', 'A vessel that carries oxygen-poor blood from the right ventricle to a lung.'),
    'pulmonary circuit': _g('pulmonary circuit', 'The route of blood from the right ventricle to the lungs and back to the left atrium.'),
    'pulmonary vein': _g('pulmonary vein', 'A vessel that carries oxygen-rich blood from a lung to the left atrium.'),
    'pulse': _g('pulse', 'The rhythmic stretching of an artery wall each time the left ventricle pushes blood into the arteries. It can be felt at the wrist and the neck.'),
    'pulse pressure': _g('pulse pressure', 'The difference between the systolic pressure and the diastolic pressure.'),
    'regurgitation': _g('regurgitation', 'Backward flow of blood through a valve that does not close fully.'),
    'resistance': _g('resistance', 'The opposition to blood flow in the vessels. It is set mostly by the diameter of the arterioles.'),
    'respiratory pump': _g('respiratory pump', 'The help that breathing gives to venous return: pressure changes in the chest and abdomen during breathing move blood in the large veins toward the heart.'),
    'sa node': _g('SA node', 'The sinoatrial node: a cluster of cells in the wall of the right atrium that starts each heartbeat. It is the heart’s natural pacemaker.'),
    'semilunar valve': _g('semilunar valve', 'A valve at the exit of a ventricle. The pulmonary valve and the aortic valve are semilunar valves.'),
    'septum': _g('septum', 'The muscular wall that separates the right and left sides of the heart.'),
    'single circulation': _g('single circulation', 'A circulation in which blood passes through the heart only once in each full trip, as in fish.'),
    'skeletal muscle pump': _g('skeletal muscle pump', 'The squeezing of veins by the skeletal muscles around them, which pushes blood toward the heart when the muscles contract.'),
    'sphygmomanometer': _g('sphygmomanometer', 'The instrument used to measure blood pressure. It has an inflatable cuff and a pressure gauge.'),
    'stenosis': _g('stenosis', 'Narrowing of a valve opening, so that blood passes through with difficulty.'),
    'stroke volume': _g('stroke volume', 'The volume of blood one ventricle pumps out in one beat.'),
    'systemic circuit': _g('systemic circuit', 'The route of blood from the left ventricle to the body tissues and back to the right atrium.'),
    'systole': _g('systole', 'The part of the cardiac cycle when a heart chamber contracts and pushes blood out.'),
    'systolic pressure': _g('systolic pressure', 'The higher number in a blood pressure reading. It is the pressure in the arteries when the ventricles contract.'),
    'total cross-sectional area': _g('total cross-sectional area', 'The openings of all the vessels of one kind added together, for example the area of all the capillaries side by side.'),
    'tricuspid valve': _g('tricuspid valve', 'The valve between the right atrium and the right ventricle.'),
    'vasoconstriction': _g('vasoconstriction', 'Narrowing of a blood vessel when the smooth muscle in its wall contracts.'),
    'vasodilation': _g('vasodilation', 'Widening of a blood vessel when the smooth muscle in its wall relaxes.'),
    'vein': _g('vein', 'A blood vessel that carries blood toward the heart. Most veins carry oxygen-poor blood, but the pulmonary veins carry oxygen-rich blood.'),
    'vena cava': _g('vena cava', 'One of the two largest veins. The superior and inferior venae cavae return oxygen-poor blood to the right atrium. The plural is venae cavae.'),
    'ventricle': _g('ventricle', 'A lower chamber of the heart that pumps blood out of the heart.'),
    'venule': _g('venule', 'A very small vein that collects blood from capillaries.'),
    'xylem': _g('xylem', 'Plant tissue that carries water and dissolved minerals from the roots to the rest of the plant.'),
}

